let rawText = $input.first().json.guardrailsInput || ""

// 2. Strip Em dashes (—) and En dashes (–), replacing them with a space
let cleanText = rawText.replace(/—/g, " ").replace(/–/g, " ");

// 3. Return the new structure mapping the cleaned text to the "response" key
return {
  json: {
    response: cleanText
  }
};

// This code takes the parsed output and prepares it for sending.
// It creates a list of messages, and the next node in your workflow
// will run once for each message in this list.

// 'items' is the standard variable in many workflow tools for the incoming data.
// If your tool uses a different variable (like '$input'), replace 'items' accordingly.
const parsedData = $input.first().json.output.response;

const messagesToSend = [];

// Define the order of the parts to ensure they are sent sequentially.
const parts = ['part_1', 'part_2', 'part_3', 'part_4', 'part_5'];

// Loop through each part from the parsed data.
for (const part of parts) {
  // By adding 'as keyof typeof parsedData', we tell the linter it's a valid key.
  const messageText = parsedData[part];

  // Check if the message part is not empty or just whitespace.
  if (messageText && messageText.trim() !== '') {
    // Add the message to our list of items to be sent.
    // The next node will receive this structured object as its input.
    messagesToSend.push({
      json: {
        message: messageText
        // You can add any other data you need for the HTTP request here.
        // For example:
        // recipientId: $input.first().json.recipientId
      }
    });
  }
}

// Return the final array of messages.
// The workflow will now treat this as a list of separate items to process.
return messagesToSend;

// This code calculates a realistic "typing" delay based on the length of the input text.
// The output can be used in a subsequent "Wait" node.

// Get the single input item provided by the "Split in Batches" node.
const item = $input.first();
const messageText = item.json.message;

// If for some reason there's no message text, default to a short 3-second delay.
if (!messageText) {
  item.json.typingDelay = 5;
  return item;
}

const textLength = messageText.length;
let minDelay;
let maxDelay;

// Define delay ranges based on the message length to simulate typing speed.
if (textLength < 50) {
  // Short message (e.g., "Okay, I can do that!")
  minDelay = 5;
  maxDelay = 7;
} else if (textLength < 150) {
  // Medium message (2-3 sentences)
  minDelay = 8;
  maxDelay = 11;
} else {
  // Long message (longer paragraphs)
  minDelay = 12;
  maxDelay = 15;
}

// Calculate a random delay within the determined range and round to a whole number.
const delayInSeconds = Math.round(Math.random() * (maxDelay - minDelay) + minDelay);

// Add the calculated delay as a new field to the item's JSON data.
// This preserves the original message and just adds the new delay value.
item.json.typingDelay = delayInSeconds;

// Return the modified item, now with the typingDelay property.
return item;
